INSERT IGNORE INTO `objects_types` VALUES (3554,3545,'Rough Thick Leather',0,0,0,0,0,0,0,0,3,10000,3000,'',0,0,0,0,0,0,'mod/MaterialsChainMod/art/2D/Items/Rough_thik_leather.png','A material used in the manufacture of leather clothes, outfits, weapons, and armor.',500,NULL,0,0);
